import{_ as n,o as t,c as i,a2 as r}from"./chunks/framework.BKIQXCqS.js";const g=JSON.parse('{"title":"Dokumentation","description":"","frontmatter":{},"headers":[],"relativePath":"de/doc.md","filePath":"de/doc.md"}'),d={name:"de/doc.md"};function s(o,e,a,l,c,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="dokumentation" tabindex="-1">Dokumentation <a class="header-anchor" href="#dokumentation" aria-label="Permalink to &quot;Dokumentation&quot;">​</a></h1><p>Die Erweiterung läuft in <strong>Chrome 120</strong> und neuer sowie in <strong>Firefox 136</strong> und neuer.</p><h2 id="user-scripts" tabindex="-1">Nutzerskripts zulassen <a class="header-anchor" href="#user-scripts" aria-label="Permalink to &quot;Nutzerskripts zulassen {#user-scripts}&quot;">​</a></h2><p>Browser führen JavaScript einer Erweiterung auf Webseiten nur mit einer eigenen Berechtigung aus. Ohne sie werden die Stile der Regeln weiterhin angewendet, das JavaScript der Regeln läuft aber nicht; das Pop-up und die Einstellungsseite zeigen dann, wie Sie es einschalten.</p><ul><li><strong>Chrome 138 und neuer:</strong> Öffnen Sie die Details der Erweiterung (<code>chrome://extensions</code> → User JavaScript and CSS → „Details“) und aktivieren Sie „Nutzer-Scripts zulassen“. Der Entwicklermodus ist nicht nötig.</li><li><strong>Chrome 120–137:</strong> Aktivieren Sie oben rechts auf <code>chrome://extensions</code> den „Entwicklermodus“. Das ist eine <a href="https://developer.chrome.com/docs/extensions/reference/api/userScripts#developer_mode_for_extension_users" target="_blank" rel="noreferrer">Vorgabe von Google</a> für jede Erweiterung mit Nutzerskripts.</li><li><strong>Firefox:</strong> Klicken Sie im Pop-up auf „Nutzerskripts zulassen“ und bestätigen Sie dies im Dialog des Browsers. Firefox kann der Erweiterung außerdem den Zugriff auf Websites entziehen: Dann zeigt das Pop-up „Zugriff auf Websites zulassen“ und die Einstellungsseite oben ein Banner mit „Zulassen“.</li></ul><h2 id="regeln" tabindex="-1">Regeln <a class="header-anchor" href="#regeln" aria-label="Permalink to &quot;Regeln&quot;">​</a></h2><p>Eine <code>Regel</code> ist in dieser Erweiterung JavaScript- und/oder CSS-Code, der auf Webseiten ausgeführt wird, die zu ihren URL-Mustern passen.</p><h3 id="url-patterns" tabindex="-1">URL-Muster <a class="header-anchor" href="#url-patterns" aria-label="Permalink to &quot;URL-Muster {#url-patterns}&quot;">​</a></h3><ul><li>Ein Muster hat die Form <code>&lt;scheme&gt;://&lt;host&gt;/&lt;path&gt;</code>: <code>https://site.com/*</code>;</li><li>Mehrere Muster werden durch Kommas getrennt: <code>https://one.com/*, https://two.com/*</code>;</li><li>Eine Ausnahme beginnt mit <code>!</code>: <code>!https://site.com/admin/*</code>.</li></ul><p>Die Erweiterung wandelt jedes Muster in das Format der <a href="https://developer.chrome.com/docs/extensions/develop/concepts/match-patterns" target="_blank" rel="noreferrer">Match Patterns</a> des Browsers um, und das Pop-up und der Zähler auf dem Symbol zeigen genau, wo der Browser die Regel ausführt.</p><p><strong>Ein Muster mit Schema</strong> wird fast so verwendet, wie es geschrieben ist:</p><table tabindex="0"><thead><tr><th>Sie schreiben</th><th>Die Regel läuft auf</th></tr></thead><tbody><tr><td><code>https://site.com/*</code></td><td><code>site.com</code> und <code>www.site.com</code>, nicht auf anderen Subdomains</td></tr><tr><td><code>https://*.site.com/*</code></td><td><code>site.com</code> und allen seinen Subdomains</td></tr><tr><td><code>https://site.com/path</code></td><td>Seiten auf <code>site.com</code> und <code>www.site.com</code>, deren Pfad mit <code>/path</code> beginnt</td></tr><tr><td><code>https://site.com</code></td><td>ganz <code>site.com</code> und <code>www.site.com</code></td></tr><tr><td><code>http*://site.com</code></td><td><code>site.com</code> und <code>www.site.com</code> über http und https</td></tr><tr><td><code>http://localhost:*/*</code></td><td>localhost auf jedem Port</td></tr></tbody></table><p><strong>Ein Muster ohne Schema</strong> steht für die Website mit ihren Subdomains, über http und https:</p><table tabindex="0"><thead><tr><th>Sie schreiben</th><th>Die Regel läuft auf</th></tr></thead><tbody><tr><td><code>site.com</code>, <code>*site.com*</code>, <code>*.site.com</code></td><td><code>site.com</code> und allen seinen Subdomains</td></tr><tr><td><code>www.site.com</code></td><td><code>www.site.com</code> und <code>site.com</code></td></tr><tr><td><code>пример.рф</code></td><td><code>пример.рф</code> und seinen Subdomains</td></tr><tr><td><code>site.com/path</code></td><td>Seiten auf <code>site.com</code> und seinen Subdomains, deren Pfad mit <code>/path</code> beginnt</td></tr><tr><td><code>localhost:3000</code></td><td>localhost auf Port 3000</td></tr><tr><td><code>/admin</code></td><td>Seiten mit <code>/admin</code> im Pfad auf jeder Website</td></tr><tr><td><code>*</code></td><td>jeder Website</td></tr></tbody></table><p>Eine Ausnahme mit Schema gilt genau so, wie sie geschrieben ist: <code>https://site.com/*, !https://www.site.com/*</code> läuft auf <code>site.com</code>, aber nicht auf <code>www.site.com</code>. Eine Ausnahme ohne Schema folgt der Tabelle oben: <code>!site.com/admin</code> schließt <code>/admin</code> auf <code>site.com</code> und seinen Subdomains aus.</p><p><strong>Ports in Firefox.</strong> In Firefox kann ein Muster keinen Port enthalten, daher wird der Port weggelassen: <code>localhost:3000</code> läuft auf localhost auf jedem Port, und eine Ausnahme mit Port schließt alle Ports des Hosts aus. Ein Muster für jede Website auf einem Port (<code>*://*:8080/*</code>) würde zu einem Muster für alle Websites, deshalb wird es in Firefox rot markiert.</p><p><strong>Rot markiert</strong> wird ein Muster, das der Browser nicht akzeptiert: ein <code>*</code> innerhalb des Hosts (<code>https://shop*.site.com/*</code>, <code>https://site.*/*</code>) oder ein Schema, auf dem die Erweiterung nicht laufen kann (<code>chrome-extension://</code>, <code>ws://</code>). Ein solches Muster wird übersprungen, die übrigen Muster der Regel funktionieren weiter. Wird eine Ausnahme abgelehnt, läuft die Regel nirgends, bis Sie sie korrigieren – sonst liefe sie auf genau den Seiten, die Sie ausgeschlossen haben.</p><h3 id="javascript-eigenschaften" tabindex="-1">JavaScript-Eigenschaften <a class="header-anchor" href="#javascript-eigenschaften" aria-label="Permalink to &quot;JavaScript-Eigenschaften&quot;">​</a></h3><p>Die Schaltflächen im Kopf des JavaScript-Bereichs:</p><ul><li><code>Isolierte Umgebung</code>: Das Skript sieht das DOM der Seite, aber nicht ihre Variablen und Funktionen.</li><li><code>Alle Frames</code>: Das Skript läuft auch in Frames, deren Adresse zur Regel passt. Jeder Frame wird einzeln mit den Mustern der Regel abgeglichen.</li><li><code>Beim Start ausführen</code>: Das Skript läuft, bevor das DOM aufgebaut ist, sonst danach, aber bevor Ressourcen wie Bilder und Frames geladen sind. Für ein solches Skript wird das Ereignis <code>DOMContentLoaded</code> nicht ausgelöst.</li></ul><h3 id="stileigenschaften" tabindex="-1">Stileigenschaften <a class="header-anchor" href="#stileigenschaften" aria-label="Permalink to &quot;Stileigenschaften&quot;">​</a></h3><p>Die Schaltflächen im Kopf des Stilbereichs:</p><ul><li><code>Sass-Präprozessor</code>: eingeschaltet (Standard) – der Stil wird als <code>Sass</code> oder <code>SCSS</code> kompiliert, die Syntax ergibt sich daraus, ob <code>{;}</code> im Code vorkommt; ausgeschaltet – der Stil wird so angewendet, wie er geschrieben ist.</li><li><code>Automatisch !important für alle Eigenschaften</code>: fügt jeder Eigenschaft des kompilierten Stils <code>!important</code> hinzu.</li><li><code>In verschachtelten Frames anwenden</code>: Der Stil gelangt auch in Frames innerhalb der Seite. Standardmäßig eingeschaltet.</li><li><code>Im Shadow DOM anwenden</code>: Der Stil gilt auch innerhalb von Webkomponenten mit offenem Shadow DOM. Standardmäßig ausgeschaltet.</li></ul><p>Ein Stil ändert sich in offenen Tabs sofort, ohne die Seite neu zu laden: wenn Sie ihn bearbeiten, die Regel aktivieren oder ihre Adresse ändern.</p><h3 id="gemeinsame-regeln" tabindex="-1">Gemeinsame Regeln <a class="header-anchor" href="#gemeinsame-regeln" aria-label="Permalink to &quot;Gemeinsame Regeln&quot;">​</a></h3><p>Mit gemeinsamen Regeln bauen Sie Abhängigkeiten zwischen Regeln auf und legen ausdrücklich fest, in welcher Reihenfolge sie geladen werden. Jede Regel lässt sich im Regelmenü als „Gemeinsame Regel“ markieren – dann erscheint sie in der Modulliste anderer Regeln. Von eingebundenen Regeln werden nur die JS- und CSS-Inhalte übernommen, ihre übrigen Eigenschaften werden ignoriert.</p><h3 id="fruhere-versionen" tabindex="-1">Frühere Versionen <a class="header-anchor" href="#fruhere-versionen" aria-label="Permalink to &quot;Frühere Versionen&quot;">​</a></h3><p>Die Erweiterung bewahrt den Code einer Regel vor jedem der letzten 10 Speichervorgänge auf: „Frühere Versionen“ im Regelmenü. Eine Version wird in den Editor übernommen und gilt, sobald Sie sie speichern. Versionen bleiben nur in diesem Browser: Sie werden weder exportiert noch in der Cloud gesichert.</p><h3 id="weitere-funktionen" tabindex="-1">Weitere Funktionen <a class="header-anchor" href="#weitere-funktionen" aria-label="Permalink to &quot;Weitere Funktionen&quot;">​</a></h3><ul><li>Die Markierung „Regel aktiviert“ wird ignoriert, wenn es sich um eine gemeinsame Regel handelt, die von einer anderen Regel eingebunden wird;</li><li>Die Markierung „In der Cloud sichern“ bedeutet nur, dass die Regel in das Cloud-Backup aufgenommen wird;</li><li>„Als Vorlage für neue Regeln verwenden“ im Regelmenü: Neue Regeln beginnen mit dem Code und den Eigenschaften dieser Regel.</li></ul><h2 id="module" tabindex="-1">Module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;Module&quot;">​</a></h2><p>Externe JS- und CSS-Module lassen sich in Regeln einbinden, sie laufen vor den Regeln. Unterstützt werden Links <code>https://...</code>, den Typ der Ressource erkennt die Erweiterung selbst.</p><p>Der Inhalt eines Moduls wird heruntergeladen und im Speicher der Erweiterung abgelegt. Aktualisiert wird er mit „Erneut herunterladen“ im Bearbeitungsfenster des Moduls oder nach Zeitplan: über die Einstellung „Bibliotheksupdates“ – manuell, täglich oder wöchentlich. Schlägt ein Download fehl, bleibt die vorherige Version des Moduls erhalten.</p><h2 id="speicher" tabindex="-1">Speicher <a class="header-anchor" href="#speicher" aria-label="Permalink to &quot;Speicher&quot;">​</a></h2><h3 id="lokaler-speicher" tabindex="-1">Lokaler Speicher <a class="header-anchor" href="#lokaler-speicher" aria-label="Permalink to &quot;Lokaler Speicher&quot;">​</a></h3><ul><li>„JSON exportieren“ speichert Ihre Regeln, Bibliotheken und Einstellungen in einer Datei.</li><li>„JSON importieren“ öffnet eine Liste der Regeln und Bibliotheken aus der Datei. „Ausgewählte hinzufügen“ fügt die markierten zu Ihren hinzu: Vorhandene Regeln werden ersetzt, ihr alter Code bleibt unter „Frühere Versionen“ erhalten. „Alles ersetzen“ ersetzt Ihre Regeln und Bibliotheken durch die aus der Datei.</li></ul><h3 id="browser-synchronisierung" tabindex="-1">Browser-Synchronisierung <a class="header-anchor" href="#browser-synchronisierung" aria-label="Permalink to &quot;Browser-Synchronisierung&quot;">​</a></h3><p>Ist im Browser die Synchronisierung eingeschaltet, lässt sich ein Backup in die Cloud Ihres Google- oder Firefox-Kontos hochladen. Dafür ist keine zusätzliche Anmeldung oder Einrichtung nötig: <code>storage.sync</code> ist der <a href="https://developer.chrome.com/docs/extensions/reference/api/storage#storage_areas" target="_blank" rel="noreferrer">Standard-Synchronisierungsbereich für Erweiterungen</a>. Backups werden manuell hochgeladen und heruntergeladen.</p><p>Der Platz ist auf 100 KB begrenzt, daher werden vor dem Hochladen die Inhalte externer Module und alle generierten Daten aus der Kopie entfernt und das Ergebnis komprimiert. Reicht der Platz trotzdem nicht, schalten Sie „In der Cloud sichern“ bei Regeln aus, die Sie im Backup nicht brauchen.</p><h2 id="mcp" tabindex="-1">Agenten (MCP) <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;Agenten (MCP) {#mcp}&quot;">​</a></h2><p>KI-Agenten – Claude Code, Codex, Gemini CLI, Cursor, VS Code, Claude Desktop und andere – können Ihre Regeln über den lokalen MCP-Server <a href="https://www.npmjs.com/package/user-js-css-mcp" target="_blank" rel="noreferrer">user-js-css-mcp</a> lesen und bearbeiten. Die Funktion ist experimentell.</p><ol><li>Öffnen Sie auf der Einstellungsseite den Bereich <strong>MCP</strong> und aktivieren Sie „MCP-Verbindungen zulassen“.</li><li>Wählen Sie Ihren Client. Der Bereich liefert einen fertigen Befehl, einen Link zur Installation mit einem Klick oder einen Konfigurationsblock, der Verbindungsschlüssel ist bereits eingetragen.</li><li>Starten Sie den Client neu: Er startet den Server selbst, und der Bereich zeigt an, dass der Client verbunden ist.</li></ol><p>Der Server läuft auf Ihrem Computer (<code>127.0.0.1</code>) und benötigt Node.js 18+ oder Bun 1.2+. Erweiterung und Server prüfen vor jeder Anfrage den Verbindungsschlüssel, sodass kein anderes Programm auf dem Computer sie nutzen kann. „Ersetzen“ neben dem Schlüssel trennt alle Clients, die mit dem alten Schlüssel eingerichtet wurden.</p><p>Ein Agent kann Regeln und Bibliotheken auflisten, lesen, durchsuchen, anlegen und ändern, herausfinden, welche Regeln auf einer Seite laufen, nachlesen, warum eine Regel nicht funktioniert, Regeln in einer Datei sichern und daraus wiederherstellen sowie eine Regel auf eine frühere Version zurücksetzen.</p>',44)])])}const m=n(d,[["render",s]]);export{g as __pageData,m as default};
